                outputGamut,
            );
        });
    }

    // Fallback: average all pixels
    const fallback = computeFallbackColor(data, pixelCount, opts.quality);
    if (!fallback) return null;
    const [r, g, b] = toOutput(fallback);
    return [createColor(r, g, b, 1, 1, outputGamut)];
