313: function iterate(pq: PQueue<VBox>, target: number, histo: Uint32Array): void {
314:     let ncolors = pq.size();
315:     let niters = 0;
316: 
317:     while (niters < MAX_ITERATIONS) {
318:         if (ncolors >= target) return;
319:         niters++;
320: 
321:         const vbox = pq.pop();
322: 
323:         if (!vbox.count()) {
324:             pq.push(vbox);
