21: const TARGETS: SwatchTarget[] = [
22:     { role: 'Vibrant',      targetL: 0.65, minL: 0.40, maxL: 0.85, targetC: 0.20, minC: 0.08 },
23:     { role: 'Muted',        targetL: 0.65, minL: 0.40, maxL: 0.85, targetC: 0.04, minC: 0.00 },
24:     { role: 'DarkVibrant',  targetL: 0.30, minL: 0.00, maxL: 0.45, targetC: 0.20, minC: 0.08 },
25:     { role: 'DarkMuted',    targetL: 0.30, minL: 0.00, maxL: 0.45, targetC: 0.04, minC: 0.00 },
26:     { role: 'LightVibrant', targetL: 0.85, minL: 0.70, maxL: 1.00, targetC: 0.20, minC: 0.08 },
27:     { role: 'LightMuted',   targetL: 0.85, minL: 0.70, maxL: 1.00, targetC: 0.04, minC: 0.00 },
28: ];
