30: // ---------------------------------------------------------------------------
31: // Scoring
32: // ---------------------------------------------------------------------------
33: 
34: const WEIGHT_L = 6;
35: const WEIGHT_C = 3;
36: const WEIGHT_POP = 1;
37: 
38: function score(
39:     color: Color,
40:     target: SwatchTarget,
41:     maxPopulation: number,
42: ): number {
43:     const { l, c } = color.oklch();
44: 
45:     // Out of lightness range → disqualified
46:     if (l < target.minL || l > target.maxL) return -Infinity;
47:     // Below minimum chroma → disqualified
48:     if (c < target.minC) return -Infinity;
49: 
50:     const lDist = 1 - Math.abs(l - target.targetL);
51:     const cDist = 1 - Math.min(Math.abs(c - target.targetC) / 0.2, 1);
52:     const pop = maxPopulation > 0 ? color.population / maxPopulation : 0;
53: 
54:     return lDist * WEIGHT_L + cDist * WEIGHT_C + pop * WEIGHT_POP;
55: }
