56:         [A * invDet, (c * h - b * i) * invDet, (b * f - c * e) * invDet],
57:         [B * invDet, (a * i - c * g) * invDet, (c * d - a * f) * invDet],
58:         [C * invDet, (b * g - a * h) * invDet, (a * e - b * d) * invDet],
59:     ];
